import gen9 from './gen9.json';
import { toId } from './toId.ts';
import type { SpeciesEntry, SpeciesFile } from './types.ts';

export { toId } from './toId.ts';

export type { SpeciesEntry, SpeciesFile, StoredSpecies } from './types.ts';

const file: SpeciesFile = gen9 as SpeciesFile;

/** Every Generation 9 species and form, in Dex order. Generated by `npm run data`. */
export const GEN9_SPECIES: readonly SpeciesEntry[] = file.species.map((species) => ({ id: toId(species.name), ...species }));

const byId = new Map(GEN9_SPECIES.map((species) => [species.id, species]));

export function findSpecies(id: string): SpeciesEntry | undefined {
  return byId.get(id);
}
